{
  global:
    Java_*;        # all JNI functions resolved by name
    JNI_OnLoad;    # defined in jni_bridge.cpp, and must stay visible: if the
                   # runtime cannot find it here it keeps searching this
                   # library's dependencies and reaches Qt's, which refuses to
                   # load outside a Qt app.
  local:
    *;             # hide everything else (Qt, toml++, purple-core, ...)
};
